	for word in s.split(\" \"):
		var trial: String = word if row.is_empty() else row+\" \"+word
		if row "'!= "" and font.get_string_size(trial,HORIZONTAL_ALIGNMENT_LEFT,-1,sz).x > width:
			txt(x,y,row,sz,c,font)
			y += step
			row = word
		else:
			row = trial
	txt(x,y,row,sz,c,font)
	return y

